/**
 * Solve the transient study and extract the probe time series in the SAME process.
 *
 * Memory-oriented variant: the solved model is never saved (a 42-step 274k-element
 * solution is ~7 GB and the E host cannot re-load it), the output time list is
 * reduced to 22 stored times, and the per-probe node arrays are collapsed to
 * min/max/mean immediately so that only one probe at a time is held in memory.
 *
 * Generated by src/run/emsolve_extract.sh from the placeholders
 *   __MODEL__ __DOMAINS__ __LABELS__ __EXPRS__
 *
 * Prints one line per stored time:
 *   TSV <t_d> <label>_min <label>_max <label>_mean ...
 * and EXTRACT_DONE at the end.
 */
import com.comsol.model.*;
import com.comsol.model.util.*;

public class SolveExtract {
    public static void main(String[] args) throws Exception {
        String modelPath = "__MODEL__";
        int[][] domGroups = new int[][] { __DOMAINS__ };
        String[] labels = new String[] { __LABELS__ };
        String[] exprs = new String[] { __EXPRS__ };

        Model model = ModelUtil.load("M", modelPath);
        ModelUtil.showProgress(false);
        System.out.println("MODEL_LOADED");
        System.out.flush();

        // study steps substituted by the caller (__STUDIES__); empty = all, in model order
        String[] studies = new String[] { __STUDIES__ };
        if (studies.length == 0) {
            studies = model.study().tags();
        }
        for (String st : studies) {
            try {
                model.study(st).feature("time").set("tlist", "__TLIST__");
                System.out.println("TLIST_SET " + st + " " + model.study(st).feature("time").getString("tlist"));
            } catch (Exception e) {
                System.out.println("TLIST_SKIP " + st + " " + e.getMessage());
            }
            System.out.flush();
            long t0 = System.currentTimeMillis();
            model.study(st).run();
            System.out.println("SOLVED " + st + " IN_MIN " + (System.currentTimeMillis() - t0) / 60000.0);
            System.out.flush();
        }

        var num = model.result().numerical();
        int n = exprs.length;
        double[][] stats = new double[n * 3][];

        for (int i = 0; i < n; i++) {
            try {
                num.create("ev" + i, "Eval");
                var ev = num.get("ev" + i);
                ev.selection().geom(2).set(domGroups[i]);
                ev.set("expr", exprs[i]);
                double[][] d = ev.getData()[0];          // [ntimes][nnodes]
                int nt = d.length;
                double[] mn = new double[nt], mx = new double[nt], sm = new double[nt];
                for (int k = 0; k < nt; k++) {
                    double[] v = d[k];
                    double a = Double.POSITIVE_INFINITY, b = Double.NEGATIVE_INFINITY, s = 0.0;
                    for (double x : v) { if (x < a) a = x; if (x > b) b = x; s += x; }
                    mn[k] = a; mx[k] = b; sm[k] = s / v.length;
                }
                double[][][] tmp = new double[1][][];
                tmp[0] = null;
                stats[3 * i] = mn; stats[3 * i + 1] = mx; stats[3 * i + 2] = sm;
                d = null;
                System.out.println("PROBE_OK " + i + " ntimes=" + nt);
            } catch (Throwable e) {
                System.out.println("PROBE_FAIL " + i + " " + e.getMessage());
            }
            System.out.flush();
        }

        double[] times = null;
        try {
            num.create("evt", "Eval");
            var te = num.get("evt");
            te.selection().geom(2).set(domGroups[0]);
            te.set("expr", "t");
            te.set("unit", "d");
            double[][] tt = te.getData()[0];
            times = new double[tt.length];
            for (int k = 0; k < tt.length; k++) times[k] = tt[k][0];
            System.out.println("TIMES_OK " + times.length);
        } catch (Throwable e) {
            System.out.println("TIMES_FAIL " + e.getMessage());
        }
        System.out.flush();

        if (times != null) {
            for (int k = 0; k < times.length; k++) {
                StringBuilder sb = new StringBuilder("TSV ");
                sb.append(times[k]);
                for (int i = 0; i < n; i++) {
                    if (stats[3 * i] == null) { sb.append(" nan nan nan"); continue; }
                    sb.append(" ").append(stats[3 * i][k])
                      .append(" ").append(stats[3 * i + 1][k])
                      .append(" ").append(stats[3 * i + 2][k]);
                }
                System.out.println(sb.toString());
            }
            System.out.flush();
        }
        System.out.println("EXTRACT_DONE");
        System.out.flush();

        // ---- ready-made plot groups so the archived solved model opens with figures ----
        try {
            String ds = "dset1";
            try {
                String[] dts = model.result().dataset().tags();
                if (dts.length > 0) ds = dts[0];
            } catch (Throwable e) { }
            int nlast = (times != null && times.length > 0) ? times.length : 1;

            try { model.result().remove("pgphi"); } catch (Throwable e) { }
            model.result().create("pgphi", "PlotGroup2D");
            model.result("pgphi").label("phi distribution");
            try { model.result("pgphi").set("data", ds); } catch (Throwable e) { }
            model.result("pgphi").create("surf1", "Surface");
            model.result("pgphi").feature("surf1").set("expr", "phi");
            model.result("pgphi").feature("surf1").set("rangecoloractive", "on");
            model.result("pgphi").feature("surf1").set("rangecolormin", 0.0);
            model.result("pgphi").feature("surf1").set("rangecolormax", 1.0);
            model.result("pgphi").feature("surf1").set("coloring", "colortable");
            model.result("pgphi").feature("surf1").set("colortable", "Inferno");
            try { model.result("pgphi").set("looplevelinput", "manual"); } catch (Throwable e) { }
            try { model.result("pgphi").set("looplevel", new int[]{nlast}); } catch (Throwable e) { }

            try { model.result().remove("pgsph"); } catch (Throwable e) { }
            model.result().create("pgsph", "PlotGroup2D");
            model.result("pgsph").label("SiC hoop stress (MPa)");
            try { model.result("pgsph").set("data", ds); } catch (Throwable e) { }
            model.result("pgsph").create("surf1", "Surface");
            model.result("pgsph").feature("surf1").set("expr", "solid.sphi/1e6");
            model.result("pgsph").feature("surf1").set("rangecoloractive", "on");
            model.result("pgsph").feature("surf1").set("rangecolormin", -250.0);
            model.result("pgsph").feature("surf1").set("rangecolormax", 650.0);
            model.result("pgsph").feature("surf1").set("coloring", "colortable");
            model.result("pgsph").feature("surf1").set("colortable", "Thermal");
            try { model.result("pgsph").set("looplevelinput", "manual"); } catch (Throwable e) { }
            try { model.result("pgsph").set("looplevel", new int[]{nlast}); } catch (Throwable e) { }
            System.out.println("PLOT_OK nlast=" + nlast);
        } catch (Throwable e) {
            System.out.println("PLOT_FAIL " + e.getMessage());
        }
        System.out.flush();

        // ---- export ready-made colour figures (curve data go back as CSV) ----
        try {
            String[] pgs = {"pgphi", "pgsph"};
            for (String pg : pgs) {
                try { model.result().export().remove("img_" + pg); } catch (Throwable e) { }
                model.result().export().create("img_" + pg, "Image");
                model.result().export("img_" + pg).set("sourceobject", pg);
                model.result().export("img_" + pg).set("size", "manualweb");
            }
            double[] targ = {100.0, 250.0, 440.0, 1000.0};
            int[] lv = new int[targ.length];
            for (int i = 0; i < targ.length; i++) {
                int best = 0;
                double bd = 1e30;
                if (times != null) {
                    for (int k = 0; k < times.length; k++) {
                        double dd = Math.abs(times[k] - targ[i]);
                        if (dd < bd) { bd = dd; best = k; }
                    }
                }
                lv[i] = best + 1;
                try { System.out.println("LVTIME " + (int) targ[i] + " -> " + times[best]); } catch (Throwable e) { }
            }
            // whole particle cross-section
            setAxis(model, "view1", 0.0, 4.68e-4, -4.68e-4, 4.68e-4);
            for (int i = 0; i < targ.length; i++) {
                try { model.result("pgphi").set("looplevelinput", "manual"); } catch (Throwable e) { }
                model.result("pgphi").set("looplevel", new int[]{lv[i]});
                model.result("pgphi").run();
                model.result().export("img_pgphi").set("pngfilename", "phi_full_" + (int) targ[i] + ".png");
                model.result().export("img_pgphi").run();
                System.out.println("IMG phi_full_" + (int) targ[i]);
            }
            // zoom on the IPyC + interface layer
            setAxis(model, "view1", 3.30e-4, 4.70e-4, -7.0e-5, 7.0e-5);
            for (int i = 0; i < targ.length; i++) {
                try { model.result("pgphi").set("looplevelinput", "manual"); } catch (Throwable e) { }
                model.result("pgphi").set("looplevel", new int[]{lv[i]});
                model.result("pgphi").run();
                model.result().export("img_pgphi").set("pngfilename", "phi_zoom_" + (int) targ[i] + ".png");
                model.result().export("img_pgphi").run();
                System.out.println("IMG phi_zoom_" + (int) targ[i]);
            }
            // SiC hoop stress at 440 d
            setAxis(model, "view1", 0.0, 4.68e-4, -4.68e-4, 4.68e-4);
            try { model.result("pgsph").set("looplevelinput", "manual"); } catch (Throwable e) { }
            model.result("pgsph").set("looplevel", new int[]{lv[2]});
            model.result("pgsph").run();
            model.result().export("img_pgsph").set("pngfilename", "sph_full_440.png");
            model.result().export("img_pgsph").run();
            setAxis(model, "view1", 3.30e-4, 4.70e-4, -7.0e-5, 7.0e-5);
            try { model.result("pgsph").set("looplevelinput", "manual"); } catch (Throwable e) { }
            model.result("pgsph").set("looplevel", new int[]{lv[2]});
            model.result("pgsph").run();
            model.result().export("img_pgsph").set("pngfilename", "sph_zoom_440.png");
            model.result().export("img_pgsph").run();
            // SiC hoop stress at 1000 d (cross-check of the stored-time selection)
            setAxis(model, "view1", 0.0, 4.68e-4, -4.68e-4, 4.68e-4);
            model.result("pgsph").set("looplevel", new int[]{lv[3]});
            model.result("pgsph").run();
            model.result().export("img_pgsph").set("pngfilename", "sph_full_1000.png");
            model.result().export("img_pgsph").run();
            System.out.println("IMG sph_full_1000");
            System.out.println("FIG_OK");
        } catch (Throwable e) {
            System.out.println("FIG_FAIL " + e.getMessage());
        }
        // ---- keep the solved model so the prepared plots can be opened later ----
        try {
            model.save("SolveExtract_M.mph");
            System.out.println("SOLVED_MODEL_SAVED");
        } catch (Throwable e) {
            System.out.println("SAVE_FAIL " + e.getMessage());
        }
        System.out.flush();
    }

    static void setAxis(Model model, String viewTag, double xmin, double xmax, double ymin, double ymax) {
        try {
            View v = model.view(viewTag);
            v.axis().set("viewscaletype", "manual");
            v.axis().set("xmin", xmin);
            v.axis().set("xmax", xmax);
            v.axis().set("ymin", ymin);
            v.axis().set("ymax", ymax);
            System.out.println("AXIS " + viewTag + " " + xmin + ".." + xmax + " / " + ymin + ".." + ymax);
        } catch (Throwable e) {
            System.out.println("AXIS_FAIL " + viewTag + " " + e.getMessage());
        }
    }
}
